'use strict';

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const PROJECT_DIR = process.env.CLAUDE_PROJECT_DIR || path.resolve(__dirname, '..', '..', '..');
const PERSONAS_DIR = path.join(PROJECT_DIR, '.claude', 'skills', 'business', 'personas');
const CROSS_PATTERNS_FILE = path.join(PROJECT_DIR, '.claude', 'agents', 'business', 'shared', 'cross-persona-patterns.json');
const SOURCES_DIR = path.join(PROJECT_DIR, '.claude', 'skills', 'business', 'knowledge_base', 'persona_sources');
const COMMONALITY_INDEX_FILE = path.join(PROJECT_DIR, '.claude', 'skills', 'business', 'knowledge_base', 'commonality-index.json');
const RETRIEVE_SCRIPT = path.join(PROJECT_DIR, '.claude', 'skills', 'business', 'knowledge_base', 'retrieve.py');
const PYTHON_BIN = path.join(PROJECT_DIR, '.claude', 'skills', '.venv', process.platform === 'win32' ? 'Scripts/python.exe' : 'bin/python3');
const AUTO_SYNC_SCRIPT = path.join(PROJECT_DIR, '.claude', 'skills', 'business', 'knowledge_base', 'auto-sync-trigger.py');

let loadLessonsForAgent;
try {
  ({ loadLessonsForAgent } = require('./lesson-loader.cjs'));
} catch { loadLessonsForAgent = () => []; }

let rankPersonaForDomain;
try {
  ({ rankPersonaForDomain } = require('./inline-weight-calculator.cjs'));
} catch { rankPersonaForDomain = () => null; }

let getFailureCasesBlock;
try {
  ({ getFailureCasesBlock } = require('./failure-case-injector.cjs'));
} catch { getFailureCasesBlock = () => null; }

const COMMONALITY_BUILDER_SCRIPT = path.join(PROJECT_DIR, '.claude', 'skills', 'business', 'knowledge_base', 'commonality-index-builder.py');
const COMMONALITY_MAX_AGE_MS = 24 * 60 * 60 * 1000; // 24 hours

let _commonalityIndex = null;
function loadCommonalityIndex() {
  if (_commonalityIndex) return _commonalityIndex;
  try {
    rebuildCommonalityIndexIfStale();
    if (!fs.existsSync(COMMONALITY_INDEX_FILE)) return {};
    _commonalityIndex = JSON.parse(fs.readFileSync(COMMONALITY_INDEX_FILE, 'utf8'));
    return _commonalityIndex;
  } catch { return {}; }
}

function rebuildCommonalityIndexIfStale() {
  try {
    if (!fs.existsSync(PYTHON_BIN) || !fs.existsSync(COMMONALITY_BUILDER_SCRIPT)) return;
    let needsRebuild = !fs.existsSync(COMMONALITY_INDEX_FILE);
    if (!needsRebuild) {
      const stat = fs.statSync(COMMONALITY_INDEX_FILE);
      needsRebuild = (Date.now() - stat.mtimeMs) > COMMONALITY_MAX_AGE_MS;
    }
    if (needsRebuild) {
      execSync(`"${PYTHON_BIN}" "${COMMONALITY_BUILDER_SCRIPT}"`, {
        cwd: path.dirname(COMMONALITY_BUILDER_SCRIPT),
        timeout: 15000,
        stdio: 'ignore'
      });
    }
  } catch { /* non-critical — use stale index if rebuild fails */ }
